public class ClickCountClassifierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void click(ClickCountClassifier panel, int clickCount) {
        panel.dispatchEvent(new java.awt.event.MouseEvent(panel,
                java.awt.event.MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(),
                0, 30, 40, clickCount, false));
    }

    static String tallies(ClickCountClassifier panel) {
        return panel.singles() + "/" + panel.doubles() + "/" + panel.rapids();
    }

    public static void main(String[] args) {
        try {
            ClickCountClassifier panel = new ClickCountClassifier();
            java.awt.Component label = find(panel, "kind");

            check("a MouseListener is registered", true, panel.getMouseListeners().length >= 1);
            check("counters start at zero", "0/0/0", tallies(panel));
            check("label starts at none", "none", textOf(label));

            click(panel, 1);
            check("one single click", "1/0/0", tallies(panel));
            check("label after a single click", "single", textOf(label));

            click(panel, 2);
            check("a double click does not also count as a single", "1/1/0", tallies(panel));
            check("label after a double click", "double", textOf(label));

            click(panel, 3);
            click(panel, 5);
            check("three or more counts as rapid", "1/1/2", tallies(panel));
            check("label after a rapid click", "rapid", textOf(label));

            click(panel, 1);
            check("single clicks keep counting", "2/1/2", tallies(panel));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

