import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class ClickCountClassifier extends JPanel {

    private final JLabel kind = new JLabel("none");
    private int singles = 0;
    private int doubles = 0;
    private int rapids = 0;

    public ClickCountClassifier() {
        kind.setName("kind");
        add(kind);
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 1) {
                    singles++;
                    kind.setText("single");
                } else if (e.getClickCount() == 2) {
                    doubles++;
                    kind.setText("double");
                } else {
                    rapids++;
                    kind.setText("rapid");
                }
            }
        });
    }

    public int singles() {
        return singles;
    }

    public int doubles() {
        return doubles;
    }

    public int rapids() {
        return rapids;
    }
}
